package com.projecteden.profile.controller;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.profile.dto.*;import com.projecteden.profile.service.ProfileService;import com.projecteden.user.domain.User;@RestController@RequestMapping("/api/profiles")public class ProfileController{private final ProfileService service;public ProfileController(ProfileService service){this.service=service;}@GetMapping("/me")public ProfileResponseDTO get(@AuthenticationPrincipal User u){return service.get(u.getId());}@PutMapping("/me")public ProfileResponseDTO update(@AuthenticationPrincipal User u,@RequestBody ProfileUpdateDTO d){return service.update(u.getId(),d);}}
